css:
.pg-chapter {
  --ink: var(--ink, #1a1a1a);
  --muted: var(--muted, #666);
  --accent: var(--accent, #003366);
  --warm: var(--warm, #cc0066);
  --line: var(--line, #ddd);
  --paper: var(--paper, #f5f5f5);

  font-family: system-ui, sans-serif;
  background-color: var(--paper);
  color: var(--ink);
  padding: 2rem 1rem;
  line-height: 1.6;
  box-sizing: border-box;
}

.pg-chapter * {
  box-sizing: border-box;
}

.pg-header {
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 1rem;
}

.pg-title {
  font-size: 24px;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--accent);
}

.pg-lead {
  font-size: 16px;
  color: var(--muted);
  margin: 0;
  font-family: serif;
}

.pg-interactive-stage {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin: 1.5rem 0;
  border-radius: 4px;
}

.pg-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  margin-bottom: 1.5rem;
}

.pg-control-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-width: 200px;
}

.pg-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
}

.pg-slider {
  width: 100%;
  accent-color: var(--accent);
}

.pg-scale-display {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  font-family: monospace;
  color: var(--muted);
}

.pg-scale-value.pg-new {
  color: var(--accent);
  font-weight: 700;
}

.pg-toggle {
  padding: 0.5rem 1rem;
  background: #fff;
  border: 1px solid var(--line);
  color: var(--ink);
  font-size: 13px;
  cursor: pointer;
  border-radius: 4px;
}

.pg-toggle[data-state="computational"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.pg-tech-status {
  font-size: 12px;
  color: var(--muted);
}

.pg-visualization {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 600px) {
  .pg-visualization {
    grid-template-columns: 1fr;
  }
}

.pg-comparison-card {
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #fafafa;
}

.pg-comparison-card.pg-new-state {
  border-color: var(--accent);
  background: #f0f4f8;
}

.pg-card-title {
  font-size: 15px;
  margin: 0 0 1rem 0;
  color: var(--ink);
}

.pg-features {
  list-style: none;
  padding: 0;
  margin: 0 0 1rem 0;
  font-size: 14px;
}

.pg-features li {
  margin-bottom: 0.5rem;
  padding-left: 1rem;
  position: relative;
}

.pg-features li::before {
  content: "•";
  position: absolute;
  left: 0;
  color: var(--muted);
}

.pg-btn-source {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  font-size: 12px;
  padding: 0.25rem 0.5rem;
  cursor: pointer;
  border-radius: 4px;
}

.pg-btn-source:hover {
  border-color: var(--ink);
  color: var(--ink);
}

.pg-acceptance-feedback {
  padding: 1rem;
  background: #fff;
  border: 1px solid var(--line);
  text-align: center;
  font-size: 14px;
  border-radius: 4px;
}

.pg-acceptance-feedback.active {
  border-color: var(--accent);
  background: #eef4ff;
  color: var(--accent);
  font-weight: 600;
}

.pg-argument-flow {
  margin-top: 2rem;
}

.pg-subtitle {
  font-size: 18px;
  margin: 0 0 1rem 0;
  color: var(--ink);
}

.pg-argument-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1rem;
  font-size: 15px;
}

.pg-argument-icon {
  font-weight: 700;
  color: var(--accent);
  min-width: 24px;
}

.pg-argument-text {
  margin: 0;
  flex: 1;
}

.pg-btn-concept {
  background: transparent;
  border: 1px dashed var(--accent);
  color: var(--accent);
  font-size: 12px;
  padding: 0.25rem 0.5rem;
  cursor: pointer;
  border-radius: 4px;
  margin-left: 0.5rem;
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}

javascript:
(function() {
  const scope = document.querySelector('.pg-chapter');
  if (!scope) return;

  const slider = scope.querySelector('#pg-scale-slider');
  const toggle = scope.querySelector('#pg-tech-toggle');
  const techStatus = scope.querySelector('.pg-tech-status');
  const feedbackBox = scope.querySelector('#pg-acceptance-box');
  const oldCard = scope.querySelector('.pg-old-state');
  const newCard = scope.querySelector('.pg-new-state');

  let state = {
    scale: 0, // 0 = old, 100 = new
    tech: 'manual' // manual or computational
  };

  function updateVisuals() {
    // Scale Slider Logic
    const scaleValue = parseInt(slider.value, 10);
    state.scale = scaleValue;

    const progress = scaleValue / 100;
    const oldOpacity = 1 - progress;
    const newOpacity = 0.2 + (progress * 0.8);

    oldCard.style.opacity = oldOpacity.toFixed(2);
    newCard.style.opacity = newOpacity.toFixed(2);

    // Tech Toggle Logic
    if (state.tech === 'computational') {
      toggle.textContent = '分布式表示';
      toggle.setAttribute('data-state', 'computational');
      techStatus.textContent = '已接入语义向量技术';
      techStatus.style.color = 'var(--accent)';
      newCard.style.borderColor = 'var(--accent)';
    } else {
      toggle.textContent = '人工分析';
      toggle.setAttribute('data-state', 'manual');
      techStatus.textContent = '未接入分布式表示';
      techStatus.style.color = 'var(--muted)';
      newCard.style.borderColor = 'var(--line)';
    }

    // Acceptance Check
    // Criteria: Scale expanded (slider > 50) AND Tech advanced (toggle = computational)
    const isScaleExpanded = scaleValue > 50;
    const isTechAdvanced = state.tech === 'computational';

    if (isScaleExpanded && isTechAdvanced) {
      feedbackBox.classList.add('active');
      feedbackBox.innerHTML = '<p class="pg-feedback-text">✓ 核心突破已确认：规模扩展性 (50 万首) + 技术先进性 (分布式表示)</p>';
    } else {
      feedbackBox.classList.remove('active');
      feedbackBox.innerHTML = '<p class="pg-feedback-text">请调整滑块至右侧并切换技术开关，以对比本研究的核心突破。</p>';
    }
  }

  // Event Listeners
  slider.addEventListener('input', updateVisuals);

  toggle.addEventListener('click', function() {
    state.tech = state.tech === 'manual' ? 'computational' : 'manual';
    updateVisuals();
  });

  // Source Button Delegation
  scope.addEventListener('click', function(e) {
    const btn = e.target.closest('button[data-source]');
    if (btn) {
      // Host kernel handles source lookup via data-source attribute
      // No action needed here except ensuring attribute exists
      const sourceId = btn.getAttribute('data-source');
      // Visual feedback only
      btn.style.background = '#eee';
      setTimeout(() => { btn.style.background = ''; }, 200);
    }

    const conceptBtn = e.target.closest('button[data-concept]');
    if (conceptBtn) {
      const conceptId = conceptBtn.getAttribute('data-concept');
      // Host kernel handles concept lookup
      conceptBtn.style.background = '#eee';
      setTimeout(() => { conceptBtn.style.background = ''; }, 200);
    }
  });

  // Initialize
  updateVisuals();
})();
